"use strict";(self.webpackChunkgp_portfolio=self.webpackChunkgp_portfolio||[]).push([["348"],{9286(e,t,n){n.r(t),n.d(t,{metadata:()=>s,default:()=>h,frontMatter:()=>o,contentTitle:()=>r,toc:()=>d,assets:()=>c});var s=JSON.parse('{"id":"RAG Project/Solution Development/rag-source-formats","title":"RAG source formats used in this project","description":"RAG systems can accept source content in a variety of formats. In this project, I tested plain text, PDF, HTML and DITA formats.","source":"@site/docs/RAG Project/2. Solution Development/rag-source-formats.mdx","sourceDirName":"RAG Project/2. Solution Development","slug":"/RAG Project/Solution Development/rag-source-formats","permalink":"/portfolio/docs/RAG Project/Solution Development/rag-source-formats","draft":false,"unlisted":false,"tags":[],"version":"current","sidebarPosition":5,"frontMatter":{"sidebar_position":5},"sidebar":"tutorialSidebar","previous":{"title":"Source data","permalink":"/portfolio/docs/RAG Project/Solution Development/source-data"},"next":{"title":"Evaluation design","permalink":"/portfolio/docs/RAG Project/Evaluation/design"}}'),a=n(4848),i=n(8453);let o={sidebar_position:5},r="RAG source formats used in this project",c={},d=[{value:"Plain text",id:"plain-text",level:2},{value:"PDF",id:"pdf",level:2},{value:"HTML",id:"html",level:2},{value:"DITA",id:"dita",level:2}];function l(e){let t={code:"code",h1:"h1",h2:"h2",header:"header",img:"img",p:"p",...(0,i.R)(),...e.components};return(0,a.jsxs)(a.Fragment,{children:[(0,a.jsx)(t.header,{children:(0,a.jsx)(t.h1,{id:"rag-source-formats-used-in-this-project",children:"RAG source formats used in this project"})}),"\n",(0,a.jsx)(t.p,{children:"RAG systems can accept source content in a variety of formats. In this project, I tested plain text, PDF, HTML and DITA formats."}),"\n",(0,a.jsx)(t.p,{children:"The sections that follow discuss the known advantages and drawbacks of each of these formats for RAG."}),"\n",(0,a.jsx)(t.h2,{id:"plain-text",children:"Plain text"}),"\n",(0,a.jsx)(t.p,{children:"To test plain text as RAG source content, I prepared plain text files containing the relevant content."}),"\n",(0,a.jsx)(t.p,{children:"Plain text lacks any formatting or semantic structure. This means, for example, that there are no heading formats, list structures, links, code markers, or any markers to indicate content purpose."}),"\n",(0,a.jsx)(t.p,{children:"Without such indicators, the RAG system has no semantic boundaries that it can use to control where chunks begin and end, and the chunks are made up of lines of undifferentiated plain text. Chunking of the source content may be deficient in areas such as structure, semantic accuracy, coherence and context preservation. This can impair the ability of the RAG system to add good contextualisation to the user\u2019s question. As a result, the LLM may not be able to return an answer of sufficient quality to the user."}),"\n",(0,a.jsx)(t.p,{children:"On the other hand, if the RAG system is provided with plain text source for items that naturally exist in plain text form, such as readme notes and configuration files, the impairment may not be significant."}),"\n",(0,a.jsx)(t.p,{children:"Additionally, the simplicity of plain text means that it is not susceptible to noise content being added to the vector database, which can be a significant drawback of PDF and HTML source."}),"\n",(0,a.jsx)(t.p,{children:"The image below shows a partial view of some of the chunks added to the vector database for plain text source:"}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Embedded chunks generated from plain text",src:n(8377).A+"",width:"836",height:"307"})}),"\n",(0,a.jsx)(t.h2,{id:"pdf",children:"PDF"}),"\n",(0,a.jsx)(t.p,{children:"PDF is designed to give an appealing visual structure to documents, but the way this is achieved comes at the cost of the file lacking a meaningful underlying structure. The PDF file consists of a sequence of characters containing textual content and presentation data. The textual content occurs on a line-by-line basis, which means that, depending on the structure of a page, the text read by the RAG splitter may not be in readable sequential order. A common situation in which this occurs is when the page has multiple columns. The RAG splitter cannot recognise this, and will create chunks composed of fragments of text arranged out of order."}),"\n",(0,a.jsx)(t.p,{children:"When PDF content is chunked by a RAG system, the splitter cannot detect semantic boundaries, and it cannot distinguish between actual textual content and the PDF\u2019s other information. As a result, chunks lack any structure and can include extraneous text that has no useful meaning. This is particularly problematic with PDF table structures, as the RAG system cannot interpret these as tables, and instead it chunks the table content as sequences of consecutive characters."}),"\n",(0,a.jsx)(t.p,{children:"PDFs can also include hidden layers containing additional text, as well as overlapping text from revisions, and text in form fields. These can add additional noise to chunks, reducing further the meaningful and coherent content in each chunk."}),"\n",(0,a.jsx)(t.p,{children:"These issues impair the RAG system\u2019s ability to find meaningful similarities between chunks and the user\u2019s question, which means that the LLM may receive a question that has not been properly contextualised."}),"\n",(0,a.jsx)(t.p,{children:"PDF is widely considered to be far less suitable format for RAG source content than any of the other formats tested as part of this investigation."}),"\n",(0,a.jsx)(t.p,{children:"Below is a partial view of some of the chunks generated from the PDF source used in this project. You can see examples here of a broken semantic boundary, extraneous text, and text embedded out of order."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Embedded chunks generated from PDF",src:n(7108).A+"",width:"836",height:"351"})}),"\n",(0,a.jsx)(t.h2,{id:"html",children:"HTML"}),"\n",(0,a.jsx)(t.p,{children:"Because of its well-defined formatting tags and clear structuring, HTML is generally considered to be a much better RAG source format than plain text or PDF. It has tags for semantically meaningful elements such as headings, lists, links, tables and code blocks, which can be readily converted into Markdown content optimised for splitting into chunks (although Markdown\u2019s limitations mean that complex tables are problematic). Inline formatting is also preserved. The splitter can easily recognise semantic boundaries, and it preserves the content structure when it creates chunks."}),"\n",(0,a.jsxs)(t.p,{children:["The splitter used in this project can remove some \u201Cnoise\u201D content, such as ",(0,a.jsx)(t.code,{children:"<script>"}),", ",(0,a.jsx)(t.code,{children:"<style>"}),", ",(0,a.jsx)(t.code,{children:"<nav>"}),", ",(0,a.jsx)(t.code,{children:"<footer>"})," and ",(0,a.jsx)(t.code,{children:"<header>"})," tags. However, HTML5 semantic tags are not converted into semantically meaningful Markdown elements. So, for example, the contents of a HTML ",(0,a.jsx)(t.code,{children:'<aside class="warning">'})," element is rendered in Markdown simply as plain text. HTML class and id attributes in general are lost in the conversion, eliminating any semantic value that they might have."]}),"\n",(0,a.jsxs)(t.p,{children:["Another important drawback of the HTML-based RAG system tested in this project is its inability to distinguish sidebar content and ",(0,a.jsx)(t.code,{children:"<form>"})," content from the main content. In fact, because these extraneous elements are chunked for every HTML file, the vector database contains about twice as many chunks as the vector databases of the other source formats. The additional vectors are associated almost exclusively with noise content. Some examples can be seen in the image below."]}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Embedded chunks generated from HTML",src:n(3208).A+"",width:"836",height:"353"})}),"\n",(0,a.jsx)(t.h2,{id:"dita",children:"DITA"}),"\n",(0,a.jsxs)(t.p,{children:["The Darwin Information Typing Architecture (DITA) is an XML-based standard for structured technical documentation. It facilitates the topic-based approach to technical writing, in which small, focused, reusable elements of content exist as individual topic files of ",(0,a.jsx)(t.code,{children:"<task>"}),", ",(0,a.jsx)(t.code,{children:"<concept>"})," or ",(0,a.jsx)(t.code,{children:"<reference>"})," type. Within these, pieces of content are contained within semantically meaningful tags that reflect their meaning and purpose, such as ",(0,a.jsx)(t.code,{children:"<prereq>"}),", ",(0,a.jsx)(t.code,{children:"<steps>"}),", ",(0,a.jsx)(t.code,{children:"<step>"}),", ",(0,a.jsx)(t.code,{children:"<cmd>"}),", and so on."]}),"\n",(0,a.jsx)(t.p,{children:"DITA is an example of structured content because its structure is semantically meaningful. Other modern examples of such systems are Semantic HTML5, AsciiDoc and MDX."}),"\n",(0,a.jsx)(t.p,{children:"By contrast, the type of HTML used in this project is sometimes referred to as semi-structured content, largely because its tags focus on presentation rather than strictly on semantic meaning."}),"\n",(0,a.jsx)(t.p,{children:"Plain text and PDF are referred to as unstructured content."}),"\n",(0,a.jsx)(t.p,{children:"Structured content is generally regarded as far preferable for RAG systems compared to other source formats, including HTML."}),"\n",(0,a.jsx)(t.p,{children:"The Markdown conversion from DITA preserves the structure and semantics the DITA content, which means the embedding model can understand the document structure and far more effectively chunk the content in line with the semantic meaning. Because DITA is not concerned with presentation, there is none of the noise content that can impair a HTML-based RAG system"}),"\n",(0,a.jsx)(t.p,{children:"The difference in quality of the chunking shown below is immediately obvious compared to PDF and HTML. Each chunk is a complete semantic unit, such as a complete procedure or set of concepts."}),"\n",(0,a.jsx)(t.p,{children:(0,a.jsx)(t.img,{alt:"Embedded chunks generated from DITA",src:n(7473).A+"",width:"836",height:"430"})})]})}function h(e={}){let{wrapper:t}={...(0,i.R)(),...e.components};return t?(0,a.jsx)(t,{...e,children:(0,a.jsx)(l,{...e})}):l(e)}},7473(e,t,n){n.d(t,{A:()=>s});let s=n.p+"assets/images/dita-format-c1b0818f773fbbc529025765d3146745.png"},3208(e,t,n){n.d(t,{A:()=>s});let s=n.p+"assets/images/html-format-d8dfeb1ab3cba57d651c4a4efe854d92.png"},7108(e,t,n){n.d(t,{A:()=>s});let s=n.p+"assets/images/pdf-format-e263494deb0acb8330c38dfca1e954ec.png"},8377(e,t,n){n.d(t,{A:()=>s});let s=n.p+"assets/images/plain-text-format-90c32f1ae8cfdf02a6feeda094ec01cc.png"},8453(e,t,n){n.d(t,{R:()=>o,x:()=>r});var s=n(6540);let a={},i=s.createContext(a);function o(e){let t=s.useContext(i);return s.useMemo(function(){return"function"==typeof e?e(t):{...t,...e}},[t,e])}function r(e){let t;return t=e.disableParentContext?"function"==typeof e.components?e.components(a):e.components||a:o(e.components),s.createElement(i.Provider,{value:t},e.children)}}}]);